-- users, categories, products and orders switch from BIGINT identity keys to
-- 5 random uppercase letters + creation date YYYYMMDD (Vietnam time), e.g. KQZMB20261010.
-- New IDs are generated by the API (internal/ids); this migration converts existing rows.

CREATE FUNCTION migration_random_id(ts TIMESTAMPTZ) RETURNS VARCHAR(13) LANGUAGE sql AS $$
    SELECT string_agg(chr(65 + floor(random() * 26)::int), '') || to_char(ts AT TIME ZONE 'Asia/Ho_Chi_Minh', 'YYYYMMDD')
    FROM generate_series(1, 5)
$$;

CREATE TEMP TABLE id_map (
    tbl     TEXT NOT NULL,
    old_id  TEXT NOT NULL,
    new_id  VARCHAR(13) NOT NULL,
    PRIMARY KEY (tbl, old_id),
    UNIQUE (tbl, new_id)
);

DO $$
DECLARE
    t TEXT;
    r RECORD;
BEGIN
    FOREACH t IN ARRAY ARRAY['users', 'categories', 'products', 'orders'] LOOP
        FOR r IN EXECUTE format('SELECT id, created_at FROM %I', t) LOOP
            LOOP
                BEGIN
                    INSERT INTO id_map VALUES (t, r.id::text, migration_random_id(r.created_at));
                    EXIT;
                EXCEPTION WHEN unique_violation THEN
                    -- Same letters on the same day: draw again.
                END;
            END LOOP;
        END LOOP;
    END LOOP;
END $$;

-- Drop every foreign key pointing at the four tables; they are recreated below.
DO $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN
        SELECT conrelid::regclass AS tbl, conname FROM pg_constraint
        WHERE contype = 'f'
          AND confrelid IN ('users'::regclass, 'categories'::regclass, 'products'::regclass, 'orders'::regclass)
    LOOP
        EXECUTE format('ALTER TABLE %s DROP CONSTRAINT %I', r.tbl, r.conname);
    END LOOP;
END $$;

-- These compare two ID columns, which would briefly have different types below; recreated at the end.
DO $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN
        SELECT conrelid::regclass AS tbl, conname FROM pg_constraint
        WHERE contype = 'c'
          AND ((conrelid = 'categories'::regclass AND pg_get_constraintdef(oid) LIKE '%parent_id <> id%')
            OR (conrelid = 'orders'::regclass AND pg_get_constraintdef(oid) LIKE '%buyer_id <> seller_id%'))
    LOOP
        EXECUTE format('ALTER TABLE %s DROP CONSTRAINT %I', r.tbl, r.conname);
    END LOOP;
END $$;

ALTER TABLE users ALTER COLUMN id DROP IDENTITY;
ALTER TABLE categories ALTER COLUMN id DROP IDENTITY;
ALTER TABLE products ALTER COLUMN id DROP IDENTITY;
ALTER TABLE orders ALTER COLUMN id DROP IDENTITY;

-- {table, column, table the column's IDs belong to}
DO $$
DECLARE
    c TEXT[];
BEGIN
    FOREACH c SLICE 1 IN ARRAY ARRAY[
        ARRAY['users', 'id', 'users'],
        ARRAY['categories', 'id', 'categories'],
        ARRAY['products', 'id', 'products'],
        ARRAY['orders', 'id', 'orders'],
        ARRAY['password_resets', 'user_id', 'users'],
        ARRAY['addresses', 'user_id', 'users'],
        ARRAY['categories', 'parent_id', 'categories'],
        ARRAY['category_translations', 'category_id', 'categories'],
        ARRAY['products', 'owner_id', 'users'],
        ARRAY['products', 'category_id', 'categories'],
        ARRAY['product_translations', 'product_id', 'products'],
        ARRAY['product_images', 'product_id', 'products'],
        ARRAY['orders', 'buyer_id', 'users'],
        ARRAY['orders', 'seller_id', 'users'],
        ARRAY['orders', 'product_id', 'products'],
        ARRAY['orders', 'cancelled_by', 'users'],
        ARRAY['point_transactions', 'user_id', 'users'],
        ARRAY['point_transactions', 'order_id', 'orders'],
        ARRAY['point_transactions', 'created_by', 'users'],
        ARRAY['conversations', 'order_id', 'orders'],
        ARRAY['conversation_members', 'user_id', 'users'],
        ARRAY['messages', 'sender_id', 'users'],
        ARRAY['messages', 'product_id', 'products']
    ] LOOP
        EXECUTE format('ALTER TABLE %I ALTER COLUMN %I TYPE VARCHAR(13) USING %I::text', c[1], c[2], c[2]);
        EXECUTE format('UPDATE %I x SET %I = m.new_id FROM id_map m WHERE m.tbl = %L AND x.%I = m.old_id',
            c[1], c[2], c[3], c[2]);
    END LOOP;
END $$;

ALTER TABLE users ADD CONSTRAINT users_id_format CHECK (id ~ '^[A-Z]{5}[0-9]{8}$');
ALTER TABLE categories ADD CONSTRAINT categories_id_format CHECK (id ~ '^[A-Z]{5}[0-9]{8}$');
ALTER TABLE products ADD CONSTRAINT products_id_format CHECK (id ~ '^[A-Z]{5}[0-9]{8}$');
ALTER TABLE orders ADD CONSTRAINT orders_id_format CHECK (id ~ '^[A-Z]{5}[0-9]{8}$');

ALTER TABLE categories ADD CONSTRAINT categories_parent_not_self CHECK (parent_id IS NULL OR parent_id <> id);
ALTER TABLE orders ADD CONSTRAINT orders_buyer_not_seller CHECK (buyer_id <> seller_id);

ALTER TABLE password_resets ADD CONSTRAINT password_resets_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id);
ALTER TABLE addresses ADD CONSTRAINT addresses_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id);
ALTER TABLE categories ADD CONSTRAINT categories_parent_id_fkey FOREIGN KEY (parent_id) REFERENCES categories (id);
ALTER TABLE category_translations ADD CONSTRAINT category_translations_category_id_fkey
    FOREIGN KEY (category_id) REFERENCES categories (id) ON DELETE CASCADE;
ALTER TABLE products ADD CONSTRAINT products_owner_id_fkey FOREIGN KEY (owner_id) REFERENCES users (id);
ALTER TABLE products ADD CONSTRAINT products_category_id_fkey FOREIGN KEY (category_id) REFERENCES categories (id);
ALTER TABLE product_translations ADD CONSTRAINT product_translations_product_id_fkey
    FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE CASCADE;
ALTER TABLE product_images ADD CONSTRAINT product_images_product_id_fkey
    FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE CASCADE;
ALTER TABLE orders ADD CONSTRAINT orders_buyer_id_fkey FOREIGN KEY (buyer_id) REFERENCES users (id);
ALTER TABLE orders ADD CONSTRAINT orders_seller_id_fkey FOREIGN KEY (seller_id) REFERENCES users (id);
ALTER TABLE orders ADD CONSTRAINT orders_product_id_fkey FOREIGN KEY (product_id) REFERENCES products (id);
ALTER TABLE orders ADD CONSTRAINT orders_cancelled_by_fkey FOREIGN KEY (cancelled_by) REFERENCES users (id);
ALTER TABLE point_transactions ADD CONSTRAINT point_transactions_user_id_fkey FOREIGN KEY (user_id) REFERENCES users (id);
ALTER TABLE point_transactions ADD CONSTRAINT point_transactions_order_id_fkey FOREIGN KEY (order_id) REFERENCES orders (id);
ALTER TABLE point_transactions ADD CONSTRAINT point_transactions_created_by_fkey
    FOREIGN KEY (created_by) REFERENCES users (id);
ALTER TABLE conversations ADD CONSTRAINT conversations_order_id_fkey FOREIGN KEY (order_id) REFERENCES orders (id);
ALTER TABLE conversation_members ADD CONSTRAINT conversation_members_user_id_fkey
    FOREIGN KEY (user_id) REFERENCES users (id);
ALTER TABLE messages ADD CONSTRAINT messages_sender_id_fkey FOREIGN KEY (sender_id) REFERENCES users (id);
ALTER TABLE messages ADD CONSTRAINT messages_product_id_fkey FOREIGN KEY (product_id) REFERENCES products (id);

DROP TABLE id_map;
DROP FUNCTION migration_random_id(TIMESTAMPTZ);
